<?php require __DIR__.'/../lib/bootstrap.php';if(admin_user())redirect('index.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=trim($_POST['email']??'');$ip=request_ip();$t=login_throttle_status($email,$ip);if($t['blocked']){$error='Muitas tentativas. Aguarde cerca de '.max(1,(int)ceil($t['seconds']/60)).' minuto(s) e tente novamente.';}elseif(attempt_login($email,$_POST['password']??'')){redirect('index.php');}else{$t=login_throttle_status($email,$ip);$error=$t['blocked']?'Muitas tentativas. O acesso foi temporariamente bloqueado.':'E-mail ou senha inválidos.';}}$name=site_name();$logo=brand_logo();?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administração • <?=e($name)?></title><link rel="stylesheet" href="../assets/css/site.css"><link rel="stylesheet" href="../assets/css/admin.css"><style><?=brand_css_vars()?></style></head><body class="admin-login"><div class="login-card"><img src="../<?=e($logo)?>" alt="<?=e($name)?>"><span class="eyebrow dark">PAINEL ADMINISTRATIVO</span><h1>Acesso da equipe</h1><p class="powered-cactus">Cactus Eventos • White Label</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post" class="form-grid one"><?=csrf_field()?><label>E-mail<input type="email" name="email" required autocomplete="username"></label><label>Senha<input type="password" name="password" required autocomplete="current-password"></label><button class="btn btn-primary">Entrar</button></form><a href="../index.php" class="text-link">← Voltar ao site</a></div></body></html>
